{
  "examples": [
    {
      "question": "Quelle est la distance maximale parcourue et le prénom du membre concerné ?",
      "sql": "SELECT MAX(T1.distance_km), T2.first_name FROM hire_record AS T1 JOIN member_profile AS T2 ON T1.member_id = T2.member_id"
    },
    {
      "question": "Quels sont les types de cycles utilisés par au moins un membre ?",
      "sql": "SELECT T1.type_name FROM cycle_type AS T1 JOIN cycle_unit AS T2 ON T1.type_id = T2.type_id JOIN hire_record AS T3 ON T2.cycle_id = T3.cycle_id JOIN member_profile AS T4 ON T3.member_id = T4.member_id GROUP BY T1.type_name HAVING COUNT ( DISTINCT T3.hire_id ) > 0"
    },
    {
      "question": "Quels sont les identifiants des cycles loués par des membres premium ?",
      "sql": "SELECT DISTINCT T3.cycle_id FROM member_profile AS T1 JOIN hire_record AS T2 ON T1.member_id = T2.member_id JOIN cycle_unit AS T3 ON T3.cycle_id = T2.cycle_id WHERE T1.membership_level = 'premium'"
    },
    {
      "question": "Donnez les identifiants, les noms et les tarifs horaires des types de cycles urbains, classés selon le nombre de vitesses puis le tarif.",
      "sql": "SELECT type_id, type_name, hourly_rate FROM cycle_type WHERE category = 'ville' ORDER BY gear_count, hourly_rate"
    },
    {
      "question": "Quels sont les identifiants distincts des locations ayant fait l'objet d'un paiement entre le 5 et le 7 janvier 2024 ?",
      "sql": "SELECT DISTINCT T1.hire_id FROM charge_entry AS T1 JOIN hire_record AS T2 ON T1.hire_id = T2.hire_id WHERE T1.paid_at >= '2024-01-05 08:43' AND T1.paid_at <= '2024-01-07 12:29'"
    },
    {
      "question": "Quel point de retrait possède le plus grand nombre de vélos disponibles ?",
      "sql": "SELECT T1.point_name FROM pickup_point AS T1 JOIN cycle_unit AS T2 ON T1.point_id = T2.point_id GROUP BY T1.point_name ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Quelle location a le montant le plus élevé ? Indiquez le prénom du membre, le montant, ainsi que les horaires de début et de fin.",
      "sql": "SELECT T2.first_name, T1.total_amount, T1.started_at, T1.ended_at FROM hire_record AS T1 JOIN member_profile AS T2 ON T1.member_id = T2.member_id GROUP BY T1.member_id ORDER BY T1.total_amount DESC LIMIT 1"
    },
    {
      "question": "Trouvez le nom du type de cycle qui a été loué le plus grand nombre de fois.",
      "sql": "SELECT T1.type_name FROM cycle_type AS T1 JOIN cycle_unit AS T2 ON T1.type_id = T2.type_id JOIN hire_record AS T3 ON T2.cycle_id = T3.cycle_id GROUP BY T1.type_name ORDER BY count(*) DESC LIMIT 1"
    },
    {
      "question": "Listez les prénoms des membres qui ont effectué une location.",
      "sql": "SELECT T2.first_name FROM hire_record AS T1 JOIN member_profile AS T2 ON T1.member_id = T2.member_id"
    },
    {
      "question": "Quels sont les identifiants des paiements dont le montant est différent de 5,5 ?",
      "sql": "SELECT charge_id FROM charge_entry EXCEPT SELECT charge_id FROM charge_entry WHERE amount = 5.5"
    },
    {
      "question": "Quels sont les identifiants des points de retrait qui accueillent exactement deux vélos ?",
      "sql": "SELECT point_id FROM cycle_unit GROUP BY point_id HAVING count(*) = 2"
    },
    {
      "question": "Affichez les prénoms des membres et le nombre de locations qu'ils ont effectuées.",
      "sql": "SELECT T2.first_name, COUNT(*) FROM hire_record AS T1 JOIN member_profile AS T2 ON T1.member_id = T2.member_id GROUP BY T2.first_name"
    },
    {
      "question": "Combien de types de cycles appartiennent à la catégorie ville ?",
      "sql": "SELECT count(*) FROM cycle_type WHERE category = 'ville'"
    },
    {
      "question": "Quels sont les identifiants des locations associées à au plus deux paiements ?",
      "sql": "SELECT T2.hire_id FROM charge_entry AS T1 JOIN hire_record AS T2 ON T1.hire_id = T2.hire_id GROUP BY T2.hire_id HAVING count(*) <= 2"
    },
    {
      "question": "Combien de vélos n'ont encore jamais été loués ?",
      "sql": "SELECT count(*) FROM cycle_unit WHERE cycle_id NOT IN (SELECT cycle_id FROM hire_record)"
    },
    {
      "question": "Combien existe-t-il de types de cycles au total ?",
      "sql": "SELECT count(*) FROM cycle_type"
    }
  ]
}

{
  "examples": [
    {
      "question": "Quel est le nom de l'employé du site « Le Jardin Central » dont les plats d'entrée commandés représentent un montant total supérieur à zéro ?",
      "sql": "SELECT T1.full_name FROM employees AS T1 JOIN dining_sites AS T2 ON T1.site_id = T2.site_id JOIN service_orders AS T3 ON T1.employee_id = T3.employee_id JOIN order_entries AS T4 ON T3.order_id = T4.order_id JOIN dishes AS T5 ON T4.dish_id = T5.dish_id WHERE T2.site_name = 'Le Jardin Central' AND T5.category_name = 'starter' GROUP BY T1.full_name HAVING SUM ( T4.unit_price ) > 0"
    },
    {
      "question": "Combien de plats sont proposés ?",
      "sql": "SELECT count(*) FROM dishes"
    },
    {
      "question": "Quelles sont les villes où se trouvent des sites de plus de 50 places ouverts avant 2020 ?",
      "sql": "SELECT city FROM dining_sites WHERE seating_capacity > 50 AND city IN ( SELECT city FROM dining_sites WHERE opening_year < 2020 )"
    },
    {
      "question": "Donnez les dates d'embauche des employés travaillant soit sur le site de Lyon, soit sur celui de Bordeaux.",
      "sql": "SELECT T1.hire_date FROM employees AS T1 JOIN dining_sites AS T2 ON T1.site_id = T2.site_id WHERE T2.city = 'Lyon' OR T2.city = 'Bordeaux'"
    },
    {
      "question": "Quel est le nombre total de convives enregistrés pour toutes les commandes ?",
      "sql": "SELECT sum(guest_count) FROM service_orders"
    },
    {
      "question": "Quels sont les taux horaires, le nombre de convives et les noms des employés, classés par ordre décroissant selon la somme du taux horaire et du nombre de convives ?",
      "sql": "SELECT T1.hourly_rate, T3.guest_count, T1.full_name FROM employees AS T1 JOIN dining_sites AS T2 ON T1.site_id = T2.site_id JOIN service_orders AS T3 ON T1.employee_id = T3.employee_id ORDER BY T1.hourly_rate + T3.guest_count DESC"
    },
    {
      "question": "Affichez les noms des 3 plats les plus chers.",
      "sql": "SELECT dish_name FROM dishes ORDER BY unit_price DESC LIMIT 3"
    },
    {
      "question": "Trouvez le nom de l'employé qui a traité une commande à emporter.",
      "sql": "SELECT T1.full_name FROM employees AS T1 JOIN service_orders AS T2 ON T1.employee_id = T2.employee_id WHERE T2.order_channel = 'takeaway'"
    },
    {
      "question": "Quelles sont les villes qui comptent plus d'un site de restauration ?",
      "sql": "SELECT city FROM dining_sites GROUP BY city HAVING count(*) > 0"
    },
    {
      "question": "Combien de commandes ont été traitées par un responsable ou passées dans un site ouvert avant 2020 ?",
      "sql": "SELECT count(*) FROM ( SELECT T1.order_id FROM service_orders AS T1 JOIN employees AS T2 ON T1.employee_id = T2.employee_id WHERE T2.role_name = 'manager' UNION SELECT T1.order_id FROM service_orders AS T1 JOIN dining_sites AS T2 ON T1.site_id = T2.site_id WHERE T2.opening_year < 2020 )"
    },
    {
      "question": "Listez les noms des plats contenant le mot « Soupe ».",
      "sql": "SELECT dish_name FROM dishes WHERE dish_name LIKE '%Soupe%'"
    },
    {
      "question": "Trouvez les noms complets et les dates d'embauche de tous les employés, classés par nom puis par date d'embauche.",
      "sql": "SELECT full_name, hire_date FROM employees ORDER BY full_name, hire_date"
    },
    {
      "question": "Quels sont les plats qui n'ont encore jamais été inclus dans une commande ?",
      "sql": "SELECT dish_name FROM dishes WHERE dish_id NOT IN (SELECT dish_id FROM order_entries)"
    },
    {
      "question": "Quelles sont les villes qui possèdent à la fois un site employant un responsable et un site de style familial ?",
      "sql": "SELECT T2.city FROM employees AS T1 JOIN dining_sites AS T2 ON T1.site_id = T2.site_id WHERE T1.role_name = 'manager' INTERSECT SELECT T2.city FROM employees AS T1 JOIN dining_sites AS T2 ON T1.site_id = T2.site_id WHERE T2.service_style = 'family'"
    },
    {
      "question": "Combien de commandes ont été enregistrées dans chaque site ?",
      "sql": "SELECT T1.site_name, count(*) FROM dining_sites AS T1 JOIN service_orders AS T2 ON T1.site_id = T2.site_id GROUP BY T1.site_id"
    },
    {
      "question": "Trouvez les noms des plats dont le prix dans une commande est supérieur à 10 et dont le prix moyen dans les commandes est supérieur à zéro.",
      "sql": "SELECT T1.dish_name FROM dishes AS T1 JOIN order_entries AS T2 ON T1.dish_id = T2.dish_id WHERE T2.unit_price > 10 INTERSECT SELECT T1.dish_name FROM dishes AS T1 JOIN order_entries AS T2 ON T1.dish_id = T2.dish_id GROUP BY T2.dish_id HAVING avg(T2.unit_price) > 0"
    }
  ]
}
